     1→import { useState, useCallback, useMemo } from "react";
     2→import type {
     3→  ActionFunctionArgs,
     4→  HeadersFunction,
     5→  LoaderFunctionArgs,
     6→} from "react-router";
     7→import { useFetcher, useLoaderData, useNavigate } from "react-router";
     8→import { useAppBridge } from "@shopify/app-bridge-react";
     9→import { authenticate } from "../shopify.server";
    10→import { boundary } from "@shopify/shopify-app-react-router/server";
    11→import db from "../db.server";
    12→import {
    13→  Page,
    14→  Layout,
    15→  Card,
    16→  BlockStack,
    17→  InlineStack,
    18→  Text,
    19→  Badge,
    20→  Button,
    21→  TextField,
    22→  Select,
    23→  Modal,
    24→  DataTable,
    25→  EmptyState,
    26→  Divider,
    27→  Box,
    28→  Tooltip,
    29→  Icon,
    30→  Checkbox,
    31→  Banner,
    32→} from "@shopify/polaris";
    33→import { PlusIcon, DeleteIcon, EditIcon } from "@shopify/polaris-icons";
    34→
    35→const DAYS_OPTIONS = [
    36→  { label: "Monday", value: "Mon" },
    37→  { label: "Tuesday", value: "Tue" },
    38→  { label: "Wednesday", value: "Wed" },
    39→  { label: "Thursday", value: "Thu" },
    40→  { label: "Friday", value: "Fri" },
    41→  { label: "Saturday", value: "Sat" },
    42→  { label: "Sunday", value: "Sun" },
    43→];
    44→
    45→export const loader = async ({ request }: LoaderFunctionArgs) => {
    46→  const { session } = await authenticate.admin(request);
    47→  const shop = session.shop;
    48→
    49→  const rules = await db.deliveryRule.findMany({
    50→    where: { shop },
    51→    orderBy: { priority: "asc" },
    52→  });
    53→
    54→  // Get unique zones from zip codes for dropdown
    55→  const zones = await db.zipCode.findMany({
    56→    where: { shop, zone: { not: null } },
    57→    select: { zone: true },
    58→    distinct: ["zone"],
    59→  });
    60→
    61→  return {
    62→    rules,
    63→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
    64→  };
    65→};
    66→
    67→export const action = async ({ request }: ActionFunctionArgs) => {
    68→  const { session } = await authenticate.admin(request);
    69→  const shop = session.shop;
    70→  const formData = await request.formData();
    71→  const intent = formData.get("intent");
    72→
    73→  if (intent === "create" || intent === "update") {
    74→    const id = String(formData.get("id") || "");
    75→    const name = String(formData.get("name") || "").trim();
    76→    const zone = String(formData.get("zone") || "").trim() || null;
    77→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
    78→    const minOrderAmount = formData.get("minOrderAmount")
    79→      ? parseFloat(String(formData.get("minOrderAmount")))
    80→      : null;
    81→    const deliveryFee = formData.get("deliveryFee")
    82→      ? parseFloat(String(formData.get("deliveryFee")))
    83→      : null;
    84→    const freeShippingAbove = formData.get("freeShippingAbove")
    85→      ? parseFloat(String(formData.get("freeShippingAbove")))
    86→      : null;
    87→    const estimatedDays =
    88→      String(formData.get("estimatedDays") || "").trim() || null;
    89→    const cutoffTime =
    90→      String(formData.get("cutoffTime") || "").trim() || null;
    91→    const daysOfWeek =
    92→      String(formData.get("daysOfWeek") || "").trim() || null;
    93→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
    94→
    95→    if (!name) return { error: "Rule name is required." };
    96→
    97→    const data = {
    98→      name,
    99→      zone,
   100→      zipCodes,
   101→      minOrderAmount,
   102→      deliveryFee,
   103→      freeShippingAbove,
   104→      estimatedDays,
   105→      cutoffTime,
   106→      daysOfWeek,
   107→      priority,
   108→    };
   109→
   110→    if (intent === "update" && id) {
   111→      await db.deliveryRule.update({ where: { id }, data });
   112→      return { success: true, action: "updated" };
   113→    } else {
   114→      await db.deliveryRule.create({ data: { shop, ...data } });
   115→      return { success: true, action: "created" };
   116→    }
   117→  }
   118→
   119→  if (intent === "delete") {
   120→    const id = String(formData.get("id"));
   121→    await db.deliveryRule.delete({ where: { id } });
   122→    return { success: true, action: "deleted" };
   123→  }
   124→
   125→  if (intent === "toggle") {
   126→    const id = String(formData.get("id"));
   127→    const isActive = formData.get("isActive") === "true";
   128→    await db.deliveryRule.update({
   129→      where: { id },
   130→      data: { isActive: !isActive },
   131→    });
   132→    return { success: true, action: "toggled" };
   133→  }
   134→
   135→  return null;
   136→};
   137→
   138→type Rule = {
   139→  id: string;
   140→  name: string;
   141→  zone: string | null;
   142→  zipCodes: string | null;
   143→  minOrderAmount: number | null;
   144→  deliveryFee: number | null;
   145→  freeShippingAbove: number | null;
   146→  estimatedDays: string | null;
   147→  cutoffTime: string | null;
   148→  daysOfWeek: string | null;
   149→  isActive: boolean;
   150→  priority: number;
   151→};
   152→
   153→export default function DeliveryRulesPage() {
   154→  const { rules, zones } = useLoaderData<typeof loader>();
   155→  const fetcher = useFetcher<typeof action>();
   156→  const shopify = useAppBridge();
   157→  const navigate = useNavigate();
   158→
   159→  const [modalOpen, setModalOpen] = useState(false);
   160→  const [editingRule, setEditingRule] = useState<Rule | null>(null);
   161→
   162→  // Form state
   163→  const [name, setName] = useState("");
   164→  const [zone, setZone] = useState("");
   165→  const [zipCodes, setZipCodes] = useState("");
   166→  const [minOrderAmount, setMinOrderAmount] = useState("");
   167→  const [deliveryFee, setDeliveryFee] = useState("");
   168→  const [freeShippingAbove, setFreeShippingAbove] = useState("");
   169→  const [estimatedDays, setEstimatedDays] = useState("");
   170→  const [cutoffTime, setCutoffTime] = useState("");
   171→  const [selectedDays, setSelectedDays] = useState<string[]>([
   172→    "Mon",
   173→    "Tue",
   174→    "Wed",
   175→    "Thu",
   176→    "Fri",
   177→  ]);
   178→  const [priority, setPriority] = useState("0");
   179→
   180→  const actionError =
   181→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
   182→
   183→  const resetForm = useCallback(() => {
   184→    setName("");
   185→    setZone("");
   186→    setZipCodes("");
   187→    setMinOrderAmount("");
   188→    setDeliveryFee("");
   189→    setFreeShippingAbove("");
   190→    setEstimatedDays("");
   191→    setCutoffTime("");
   192→    setSelectedDays(["Mon", "Tue", "Wed", "Thu", "Fri"]);
   193→    setPriority("0");
   194→    setEditingRule(null);
   195→  }, []);
   196→
   197→  const openCreate = useCallback(() => {
   198→    resetForm();
   199→    setModalOpen(true);
   200→  }, [resetForm]);
   201→
   202→  const openEdit = useCallback((rule: Rule) => {
   203→    setEditingRule(rule);
   204→    setName(rule.name);
   205→    setZone(rule.zone || "");
   206→    setZipCodes(rule.zipCodes || "");
   207→    setMinOrderAmount(rule.minOrderAmount != null ? String(rule.minOrderAmount) : "");
   208→    setDeliveryFee(rule.deliveryFee != null ? String(rule.deliveryFee) : "");
   209→    setFreeShippingAbove(
   210→      rule.freeShippingAbove != null ? String(rule.freeShippingAbove) : "",
   211→    );
   212→    setEstimatedDays(rule.estimatedDays || "");
   213→    setCutoffTime(rule.cutoffTime || "");
   214→    setSelectedDays(rule.daysOfWeek ? rule.daysOfWeek.split(",") : []);
   215→    setPriority(String(rule.priority));
   216→    setModalOpen(true);
   217→  }, []);
   218→
   219→  const handleSave = useCallback(() => {
   220→    const fd = new FormData();
   221→    fd.set("intent", editingRule ? "update" : "create");
   222→    if (editingRule) fd.set("id", editingRule.id);
   223→    fd.set("name", name);
   224→    fd.set("zone", zone);
   225→    fd.set("zipCodes", zipCodes);
   226→    fd.set("minOrderAmount", minOrderAmount);
   227→    fd.set("deliveryFee", deliveryFee);
   228→    fd.set("freeShippingAbove", freeShippingAbove);
   229→    fd.set("estimatedDays", estimatedDays);
   230→    fd.set("cutoffTime", cutoffTime);
   231→    fd.set("daysOfWeek", selectedDays.join(","));
   232→    fd.set("priority", priority);
   233→    fetcher.submit(fd, { method: "POST" });
   234→    setModalOpen(false);
   235→    resetForm();
   236→    shopify.toast.show(editingRule ? "Rule updated" : "Rule created");
   237→  }, [
   238→    editingRule,
   239→    name,
   240→    zone,
   241→    zipCodes,
   242→    minOrderAmount,
   243→    deliveryFee,
   244→    freeShippingAbove,
   245→    estimatedDays,
   246→    cutoffTime,
   247→    selectedDays,
   248→    priority,
   249→    fetcher,
   250→    resetForm,
   251→    shopify,
   252→  ]);
   253→
   254→  const handleDelete = useCallback(
   255→    (id: string) => {
   256→      const fd = new FormData();
   257→      fd.set("intent", "delete");
   258→      fd.set("id", id);
   259→      fetcher.submit(fd, { method: "POST" });
   260→      shopify.toast.show("Rule deleted");
   261→    },
   262→    [fetcher, shopify],
   263→  );
   264→
   265→  const handleToggle = useCallback(
   266→    (id: string, isActive: boolean) => {
   267→      const fd = new FormData();
   268→      fd.set("intent", "toggle");
   269→      fd.set("id", id);
   270→      fd.set("isActive", String(isActive));
   271→      fetcher.submit(fd, { method: "POST" });
   272→    },
   273→    [fetcher],
   274→  );
   275→
   276→  const toggleDay = useCallback(
   277→    (day: string) => {
   278→      setSelectedDays((prev) =>
   279→        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
   280→      );
   281→    },
   282→    [],
   283→  );
   284→
   285→  const zoneOptions = [
   286→    { label: "All zones", value: "" },
   287→    ...zones.map((z) => ({ label: z, value: z })),
   288→  ];
   289→
   290→  const tableRows = (rules as Rule[]).map((rule) => [
   291→    <InlineStack gap="200" blockAlign="center" key={`name-${rule.id}`}>
   292→      <Text as="span" fontWeight="bold">
   293→        {rule.name}
   294→      </Text>
   295→      <Badge tone={rule.isActive ? "success" : undefined}>
   296→        {rule.isActive ? "Active" : "Inactive"}
   297→      </Badge>
   298→    </InlineStack>,
   299→    rule.zone || "All",
   300→    rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free",
