    99→export const loader = async ({ request }: LoaderFunctionArgs) => {
   100→  const { session, billing } = await authenticate.admin(request);
   101→  const shop = session.shop;
   102→
   103→  // Sync subscription status from Shopify
   104→  try {
   105→    const billingCheck = await billing.check({
   106→      plans: ALL_PAID_PLANS,
   107→      isTest: process.env.NODE_ENV !== "production",
   108→    });
   109→
   110→    const subscription = await syncSubscriptionFromShopify(
   111→      shop,
   112→      billingCheck.appSubscriptions ?? [],
   113→    );
   114→
   115→    return { subscription };
   116→  } catch {
   117→    // Fallback to DB
   118→    const subscription = await getShopSubscription(shop);
   119→    return { subscription };
   120→  }
   121→};
   122→
   123→// ─── Action ───────────────────────────────────────────────────────────────────
   124→
   125→export const action = async ({ request }: ActionFunctionArgs) => {
   126→  const { session, billing } = await authenticate.admin(request);
   127→  const shop = session.shop;
   128→  const formData = await request.formData();
   129→  const intent = String(formData.get("intent"));
   130→
   131→  if (intent === "subscribe") {
   132→    const plan = String(formData.get("plan"));
   133→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
   134→
   135→    try {
   136→      const confirmationUrl = await billing.request({
   137→        plan,
   138→        isTest: process.env.NODE_ENV !== "production",
   139→        returnUrl,
   140→      });
   141→      return { confirmationUrl };
   142→    } catch (err) {
   143→      return { error: "Failed to initiate subscription. Please try again." };
   144→    }
   145→  }
   146→
   147→  if (intent === "cancel") {
   148→    try {
   149→      const sub = await getShopSubscription(shop);
   150→
   151→      if (sub.shopifySubscriptionId) {
   152→        await billing.cancel({
   153→          subscriptionId: sub.shopifySubscriptionId,
   154→          isTest: process.env.NODE_ENV !== "production",
   155→          prorate: true,
   156→        });
   157→      }
   158→
   159→      await cancelShopSubscription(shop);
   160→      return { success: true, message: "Subscription cancelled. You are now on the Free plan." };
   161→    } catch {
   162→      return { error: "Failed to cancel subscription. Please try again." };
   163→    }
   164→  }
   165→
   166→  return null;
   167→};
