    43→export const loader = async ({ request }: LoaderFunctionArgs) => {
    44→  const { session } = await authenticate.admin(request);
    45→  const shop = session.shop;
    46→
    47→  const entries = await db.waitlistEntry.findMany({
    48→    where: { shop },
    49→    orderBy: { createdAt: "desc" },
    50→  });
    51→
    52→  const stats = {
    53→    total: entries.length,
    54→    waiting: entries.filter((e) => e.status === "waiting").length,
    55→    notified: entries.filter((e) => e.status === "notified").length,
    56→    converted: entries.filter((e) => e.status === "converted").length,
    57→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
    58→  };
    59→
    60→  return { entries, stats };
    61→};
    62→
    63→export const action = async ({ request }: ActionFunctionArgs) => {
    64→  const { session } = await authenticate.admin(request);
    65→  const shop = session.shop;
    66→  const formData = await request.formData();
    67→  const intent = formData.get("intent");
    68→
    69→  if (intent === "add") {
    70→    const email = String(formData.get("email") || "").trim().toLowerCase();
    71→    const zipCode = String(formData.get("zipCode") || "")
    72→      .trim()
    73→      .toUpperCase();
    74→    const note = String(formData.get("note") || "").trim() || null;
    75→
    76→    if (!email || !zipCode) return { error: "Email and zip code are required." };
    77→
    78→    try {
    79→      await db.waitlistEntry.create({
    80→        data: { shop, email, zipCode, note },
    81→      });
    82→      return { success: true, action: "added" };
    83→    } catch {
    84→      return { error: "This email is already on the waitlist for this zip code." };
    85→    }
    86→  }
    87→
    88→  if (intent === "delete") {
    89→    const id = String(formData.get("id"));
    90→    await db.waitlistEntry.delete({ where: { id } });
    91→    return { success: true, action: "deleted" };
    92→  }
    93→
    94→  if (intent === "update-status") {
    95→    const id = String(formData.get("id"));
    96→    const status = String(formData.get("status"));
    97→    await db.waitlistEntry.update({ where: { id }, data: { status } });
    98→    return { success: true, action: "updated" };
    99→  }
   100→
   101→  if (intent === "bulk-notify") {
   102→    const zipCode = String(formData.get("zipCode") || "")
   103→      .trim()
   104→      .toUpperCase();
   105→    if (!zipCode) return { error: "Zip code is required." };
   106→
   107→    const updated = await db.waitlistEntry.updateMany({
   108→      where: { shop, zipCode, status: "waiting" },
   109→      data: { status: "notified" },
   110→    });
   111→
   112→    return {
   113→      success: true,
   114→      action: "bulk-notify",
   115→      count: updated.count,
   116→      zipCode,
   117→    };
   118→  }
   119→
   120→  if (intent === "delete-all-notified") {
   121→    const deleted = await db.waitlistEntry.deleteMany({
   122→      where: { shop, status: "notified" },
   123→    });
   124→    return { success: true, action: "deleted-notified", count: deleted.count };
   125→  }
   126→
   127→  return null;
   128→};
